@materialized_view(
    name=_n("journey_clinical.form_adult_capacity_assessment"),
    refresh_policy="auto",
)
def form_adult_capacity_assessment():
    # Build the declared dataset: Adult capacity admission assessment: one row per form instance
    # with configured questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["adult_capacity_assessment"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("adult_capacity_assessment")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("patient_has_capacity_to_consent", "CODED"),
        *_single_aggregations("consider_dols_review_reference_text", "CODED"),
        *_single_aggregations("capacity_assessment_calculation", "NUMERIC"),
        *_single_aggregations("impairment_disturbance_of_mind_or_brain", "CODED"),
        *_single_aggregations("capacity_assessment_outcome", "CODED"),
        *_single_aggregations("might_the_impairement_affect_decision", "CODED"),
        *_single_aggregations("additional_support_to_help_make_decision", "TEXT"),
        *_single_aggregations("patient_understands_decision_to_be_made", "CODED"),
        *_single_aggregations("supporting_evidence", "TEXT"),
        *_single_aggregations("patient_retains_info_to_make_decision", "CODED"),
        *_single_aggregations("patient_weighs_info_to_make_decision", "CODED"),
        *_single_aggregations("able_to_communicate_decision_by_any_mean", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")


